def sf(x, default=None):
    """Safe float conversion"""
    if x is None or str(x).strip() == '':
        return default
    try:
        return float(str(x).strip())
    except (ValueError, TypeError):
        return default

def si(x, default=0):
    try:
        return int(float(str(x).strip()))
    except:
        return default

def mean(vals):
    v = [x for x in vals if x is not None]
    return sum(v) / len(v) if v else 0.0

def sd(vals):
    v = [x for x in vals if x is not None]
    n = len(v)
    if n < 2:
        return 0.0
    m = sum(v) / n
    return (sum((x - m) ** 2 for x in v) / (n - 1)) ** 0.5

def median(vals):
    v = sorted(x for x in vals if x is not None)
    n = len(v)
    if n == 0:
        return 0.0
    if n % 2 == 1:
        return v[n // 2]
    return (v[n // 2 - 1] + v[n // 2]) / 2

def pct(count, total):
    return (count / total * 100) if total > 0 else 0.0

def pearson(x, y):
    pairs = [(xi, yi) for xi, yi in zip(x, y) if xi is not None and yi is not None]
    n = len(pairs)
    if n < 3:
        return 0.0, 1.0, n
    xv, yv = zip(*pairs)
    mx, my = sum(xv) / n, sum(yv) / n
    sxx = sum((xi - mx) ** 2 for xi in xv)
    syy = sum((yi - my) ** 2 for yi in yv)
    sxy = sum((xi - mx) * (yi - my) for xi, yi in zip(xv, yv))
    if sxx == 0 or syy == 0:
        return 0.0, 1.0, n
    r = sxy / (sxx * syy) ** 0.5
    r = max(-1.0, min(1.0, r))
    if abs(r) >= 0.9999:
        return r, 0.0001, n
    t = r * ((n - 2) / (1 - r * r + 1e-15)) ** 0.5
    df = n - 2
    p = (df / (df + t * t)) ** (df / 2)
    return r, p, n

def fmt_p(p):
    if p < 0.001:
        return "P < 0.001"
    return f"P = {p:.3f}"

def fmt_r(r, p, n=None):
    s = f"r = {r:+.2f}, {fmt_p(p)}"
    if n:
        s += f", n = {n}"
    return s

def odds_ratio_2x2(a, b, c, d):
    """OR from 2x2 table: a=events_exposed, b=nonevents_exposed, c=events_ref, d=nonevents_ref"""
    if b == 0 or c == 0:
        return 1.0, "NA"
    or_val = (a * d) / (b * c)
    se = (1 / max(a, 0.5) + 1 / max(b, 0.5) + 1 / max(c, 0.5) + 1 / max(d, 0.5)) ** 0.5
    lo = math.exp(math.log(max(or_val, 0.001)) - 1.96 * se)
    hi = math.exp(math.log(max(or_val, 0.001)) + 1.96 * se)
    return or_val, f"{lo:.2f}\u2013{hi:.2f}"

def concordance(outcome, score):
    pos = [s for s, o in zip(score, outcome) if o == 1]
    neg = [s for s, o in zip(score, outcome) if o == 0]
    conc = 0
    total = 0
    for sp in pos:
        for sn in neg:
            total += 1
            if sp > sn:
                conc += 1
            elif sp == sn:
                conc += 0.5
    return conc / max(total, 1)


