    S['n_stabilising_targets'] = len(stab_stabilising)
    if stab_stabilising:
        best_target = min(stab_stabilising, key=lambda x: x[1])
        S['best_target_pos'] = best_target[0].get('position', best_target[0].get('pos', 'unknown'))
        S['best_target_mut'] = best_target[0].get('best_mutation', best_target[0].get('mutation', 'unknown'))
